script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    switch (api.state.selectedType) {
        case 'group':
            return api.state.hideGroupEmptyState;
        case 'service':
            return api.state.hideServiceEmptyState;
    }
    return true;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let label = "";
    switch (api.state.selectedType) {
        case 'group':
            label = helpers.translateSync("To see CMDB Group Dashboard you must create at least one CMDB group of type health");
            break;
        case 'service':
            label = helpers.translateSync("To see CMDB Service Dashboard the 'Event Management and Service Mapping Core' plugin is required");
            break;
    }
    return {
        "label": label,
        "level": 1
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    switch (api.state.selectedType) {
        case 'group':
            return !api.state.hideGroupEmptyState;
        case 'service':
            return !api.state.hideServiceEmptyState;
    }
    return false;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        event: 'Health parent card click',
        value: {
            'Card name': 'Completeness'
        }
    };
}

